class Solution {
public:
    vector<int> minimumWeight(vector<vector<int>>& edges, vector<vector<int>>& queries) {
        int n = (int)edges.size() + 1;
        vector<vector<pair<int,int>>> g(n);
        for (auto &e : edges) {
            g[e[0]].push_back({e[1],e[2]});
            g[e[1]].push_back({e[0],e[2]});
        }
        const int LOG = 18;
        vector<vector<int>> up(LOG, vector<int>(n));
        vector<int> depth(n,0), order(1,0);
        vector<long long> dist(n,0);
        up[0][0] = 0;
        for (int i=0;i<(int)order.size();++i) {
            int u=order[i];
            for (auto e:g[u]) {
                int v=e.first;
                if (v==up[0][u] && u!=0) continue;
                up[0][v]=u; depth[v]=depth[u]+1;
                dist[v]=dist[u]+e.second; order.push_back(v);
            }
        }
        for (int j=1;j<LOG;++j)
            for (int v=0;v<n;++v) up[j][v]=up[j-1][up[j-1][v]];
        auto lca = [&](int a,int b) {
            if(depth[a]<depth[b]) swap(a,b);
            int d=depth[a]-depth[b];
            for(int j=0;j<LOG;++j) if(d&(1<<j)) a=up[j][a];
            if(a==b) return a;
            for(int j=LOG-1;j>=0;--j) if(up[j][a]!=up[j][b]) {
                a=up[j][a]; b=up[j][b];
            }
            return up[0][a];
        };
        auto distance = [&](int a,int b) -> long long {
            return dist[a]+dist[b]-2*dist[lca(a,b)];
        };
        vector<int> ans;
        for(auto &q:queries) {
            long long sum=distance(q[0],q[1])+distance(q[0],q[2])+distance(q[1],q[2]);
            ans.push_back((int)(sum/2));
        }
        return ans;
    }
};
